
.char-panel {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.bars-section {
  display: flex;
  flex-direction: column;
  gap: 6px;
  padding: 8px;
  background: var(--c-bg-section);
  border-radius: 6px;
  border: 1px solid var(--c-border);
}

.info-section {
  display: flex;
  flex-direction: column;
  gap: 4px;
  padding: 8px;
  background: var(--c-bg-section);
  border-radius: 6px;
  border: 1px solid var(--c-border);
}

.info-row {
  display: flex;
  gap: 8px;
  align-items: flex-start;
  font-size: 0.82rem;
}

.info-label {
  color: var(--c-text-dim);
  white-space: nowrap;
  min-width: 58px;
}

.info-value {
  color: var(--c-text);
  flex: 1;
  word-break: break-all;
}

.thought {
  font-style: italic;
  color: var(--c-text-dim);
}

.body-section {
  background: var(--c-bg-section);
  border-radius: 6px;
  border: 1px solid var(--c-border);
  overflow: hidden;
}

.section-title {
  padding: 6px 10px;
  font-weight: bold;
  font-size: 0.85rem;
  background: var(--c-bg-deep);
  border-bottom: 1px solid var(--c-border);
  color: var(--c-accent-pink);
}

.body-grid {
  display: flex;
  flex-direction: column;
}

.body-row {
  display: flex;
  align-items: flex-start;
  padding: 5px 10px;
  border-bottom: 1px solid var(--c-border);
  font-size: 0.8rem;
  transition: background 0.15s;

  &:last-child { border-bottom: none; }
  &:hover { background: rgba(107, 91, 149, 0.1); }
}

.body-icon {
  width: 20px;
  flex-shrink: 0;
  text-align: center;
}

.body-part {
  width: 36px;
  flex-shrink: 0;
  color: var(--c-text-dim);
  font-weight: bold;
}

.body-desc {
  flex: 1;
  color: var(--c-text);
  word-break: break-all;
  line-height: 1.4;
}
